#!/usr/bin/env python3
"""Validate only metadata, then feed the actual compiled Java child with real FDs."""
import json,os,pathlib,signal,subprocess,sys
sys.path.insert(0,str(pathlib.Path(__file__).resolve().parent))
from format_io import normalize
HERE=pathlib.Path(__file__).resolve().parent
if os.geteuid()==0:raise SystemExit('Run as an ordinary nonroot user.')
try:data=normalize(sys.stdin.buffer.read(32*1024**2+1))
except (ValueError,TypeError,KeyError,UnicodeError,RecursionError,OverflowError):
    print('{"error":"INPUT"}');raise SystemExit(0)
proc=None
signals={signal.SIGINT,signal.SIGTERM}
def interrupted(sig,frame):
    for s in signals:signal.signal(s,signal.SIG_IGN)
    raise KeyboardInterrupt()
for s in signals:signal.signal(s,interrupted)
try:
    signal.pthread_sigmask(signal.SIG_BLOCK,signals)
    try:
        proc=subprocess.Popen([sys.executable,'-I','-B',str(HERE/'launch.py'),sys.argv[1] if len(sys.argv)>1 else '/workspace/tmp/classes'],stdin=subprocess.PIPE,close_fds=True,
            env={'PATH':'/opt/java/bin:/usr/local/bin:/usr/bin:/bin','HOME':'/workspace','LANG':'C','LC_ALL':'C','TMPDIR':'/workspace/tmp','PYTHONUNBUFFERED':'1','PYTHONDONTWRITEBYTECODE':'1','PYTHONHASHSEED':'0','OPENBLAS_NUM_THREADS':'1','OMP_NUM_THREADS':'1','MKL_NUM_THREADS':'1'})
    finally:signal.pthread_sigmask(signal.SIG_UNBLOCK,signals)
    proc.communicate(data)
    status=proc.returncode
except KeyboardInterrupt:status=130
finally:
    for s in signals:signal.signal(s,signal.SIG_IGN)
    if proc is not None:
        if proc.poll() is None:proc.kill()
        proc.wait(timeout=5)
raise SystemExit(status)
"""Input constructors only; no receive, PN-reconstruction or canonicalization model."""
def v(value,width=None):
    if width is None:width=next(w for w in [1,2,4,8] if value<2**(8*w-2))
    if width not in [1,2,4,8] or not 0<=value<2**(8*width-2):raise ValueError('varint')
    return (([1,2,4,8].index(width)<<(8*width-2))|value).to_bytes(width,'big')
def envelope(level,pn,body,cid=b'\xaa',scid=b'\xbb',token=b'',width=1,phase=0,spin=0,length_width=None):
    number=(pn%(2**(8*width))).to_bytes(width,'big')
    if level=='A':return bytes([0x40|(spin<<5)|(phase<<2)|(width-1)])+cid+number+body
    head=bytes([(0xc0 if level=='I' else 0xe0)|(width-1)])+b'\0\0\0\1'+bytes([len(cid)])+cid+bytes([len(scid)])+scid
    if level=='I':head+=v(len(token))+token
    return head+v(width+len(body),length_width)+number+body
def stream(sid,off,data,fin=False,offset=True,length=True):
    return bytes([8|(4 if offset else 0)|(2 if length else 0)|int(fin)])+v(sid)+(v(off) if offset else b'')+(v(len(data)) if length else b'')+data
def crypto(off,data):return b'\x06'+v(off)+v(len(data))+data
def datagram(wire,auth=(0,)):return {'datagram':{'wire':wire.hex(),'auth':list(auth)}}
def trace(events,connection=2**62-1,stream_credit=2**62-1,bidi=2**60,uni=2**60,cids=4,local_bidi=2,local_uni=2,local_cids=('aa','bb'),received=None):
    return {'limits':{'connection':connection,'stream':stream_credit,'bidi':bidi,'uni':uni,'cids':cids},'local':{'bidi':local_bidi,'uni':local_uni,'cids':list(local_cids)},'peer':{'cid':'cc','token':'00'*16},'received':received or {'I':None,'H':None,'A':None},'events':events}
